#!/usr/bin/env bash
# Shared settings for the lab scripts. Source this file; do not run it.
export MSYS_NO_PATHCONV=1            # stop Git Bash rewriting /opt/... paths
LAB_ENV_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && (pwd -W 2>/dev/null || pwd))"   # pwd -W: Windows path for Docker on Git Bash
LAB_ROOT="$(cd "$LAB_ENV_DIR/../.." && (pwd -W 2>/dev/null || pwd))"
COMPOSE=(docker compose -f "$LAB_ENV_DIR/docker-compose.yml")
ASE=cdc-lab-sybase; KAFKA=cdc-lab-kafka; CONNECT=cdc-lab-connect
CONNECT_URL=http://localhost:8083
CONNECTOR_NAME=sybase-cdc-phoenix
TOPIC=${TOPIC:-sybase.phoenix_test.payment}

# sa password: the public default of the ASE image (not a secret). Used only for one-time setup (DDL, accounts).
SA_PASSWORD=myPassword
# Passwords of the two lab accounts are generated by create-accounts.sh into this git-ignored file.
LAB_SECRETS="$LAB_ENV_DIR/.lab-secrets"
[ -f "$LAB_SECRETS" ] && source "$LAB_SECRETS"

# isql against the lab database; SQL on stdin. Usage: ase_sql_as <login> <password>
ase_sql_as() {
  docker exec -i "$ASE" bash -c "source /opt/sybase/SYBASE.sh; isql -U$1 -P$2 -SMYSYBASE -w250 -Dphoenix_test" | grep -v '^\s*$'
}
ase_sql()   { ase_sql_as sa "$SA_PASSWORD"; }                 # sa: setup and DDL only
ase_admin() { ase_sql_as cdc_admin "${CDC_ADMIN_PASSWORD:?run lab/env/create-accounts.sh first}"; }   # replication_role only
ase_app()   { ase_sql_as cdc_app "${CDC_APP_PASSWORD:?run lab/env/create-accounts.sh first}"; }       # DML on the sample tables only

wait_for() {  # wait_for <description> <timeout-seconds> <command...>
  local what=$1 limit=$2; shift 2
  local t=0
  until "$@" >/dev/null 2>&1; do
    t=$((t + 3)); [ $t -ge "$limit" ] && { echo "TIMEOUT waiting for $what" >&2; return 1; }
    sleep 3
  done
  echo "ok: $what"
}
